-- Column layout of RWP Shop tables the importer reads (names and types only), for tests.
CREATE TABLE "customer" (
  "telegram_id" bigint,
  "created_at" timestamp with time zone,
  "language" character varying,
  "is_blocked" boolean,
  "trial_used" boolean,
  "tg_username" text,
  "tg_first_name" text,
  "tg_last_name" text,
  "is_blocked_by_user" boolean,
  "is_suspicious" boolean,
  "is_whitelisted" boolean,
  "is_partner" boolean,
  "pending_promo_id" bigint,
  "email" character varying,
  "last_activity_at" timestamp without time zone,
  "lead_score" integer,
  "lead_temperature" character varying,
  "admin_notes" text,
  "admin_tag" character varying,
  "email_verified" boolean,
  "id" uuid,
  "referral_code" character varying,
  "is_superadmin" boolean,
  "metadata" jsonb,
  "google_id" character varying,
  "google_email" character varying,
  "yandex_id" character varying,
  "yandex_email" character varying,
  "discount_percent" integer,
  "is_abuser" boolean,
  "abuse_flagged_at" timestamp with time zone,
  "vk_id" character varying,
  "vk_email" character varying,
  "apple_id" character varying,
  "apple_email" character varying,
  "bot_id" bigint,
  "pd_consent_at" timestamp with time zone,
  "terms_consent_at" timestamp with time zone
);
CREATE TABLE "subscription" (
  "id" bigint,
  "name" character varying,
  "remnawave_uuid" uuid,
  "subscription_link" text,
  "expire_at" timestamp with time zone,
  "plan_id" bigint,
  "is_primary" boolean,
  "devices_count" integer,
  "autopay_enabled" boolean,
  "autopay_plan_id" bigint,
  "autopay_months" integer,
  "autopay_failed_attempts" integer,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "autopay_last_attempt_at" timestamp with time zone,
  "autopay_notified_at" timestamp with time zone,
  "extra_devices" integer,
  "remnawave_id" bigint,
  "customer_id" uuid,
  "share_token" character varying,
  "parent_subscription_id" bigint,
  "autopay_period_unit" character varying,
  "kind" character varying,
  "bot_id" bigint,
  "traffic_autopay_enabled" boolean,
  "traffic_autopay_charged_at" timestamp with time zone,
  "traffic_autopay_failed_attempts" integer,
  "remnawave_updated_at" timestamp with time zone
);
CREATE TABLE "purchase" (
  "id" bigint,
  "amount" numeric,
  "created_at" timestamp with time zone,
  "period" integer,
  "paid_at" timestamp with time zone,
  "currency" character varying,
  "expire_at" timestamp with time zone,
  "status" character varying,
  "invoice_type" character varying,
  "plan_id" bigint,
  "partner_id" bigint,
  "promo_id" bigint,
  "original_amount" numeric,
  "operation_type" character varying,
  "external_uuid" uuid,
  "provider_id" text,
  "provider_url" text,
  "subscription_id" bigint,
  "traffic_amount" bigint,
  "device_count" integer,
  "is_send_receipt_to_moy_nalog" boolean,
  "receipt_moy_nalog_id" text,
  "processing_started_at" timestamp with time zone,
  "processing_last_error" text,
  "processing_attempts" integer,
  "traffic_used_before_bytes" bigint,
  "traffic_limit_before_bytes" bigint,
  "customer_id" uuid,
  "period_unit" character varying,
  "payment_method_id" text,
  "bot_id" bigint,
  "create_new_subscription" boolean
);
CREATE TABLE "plan" (
  "id" bigint,
  "name" text,
  "traffic_limit" integer,
  "device_limit" integer,
  "is_active" boolean,
  "is_default" boolean,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "internal_squads" text,
  "external_squad_uuid" text,
  "remnawave_tag" text,
  "sort_order" integer,
  "traffic_limit_strategy" character varying,
  "is_hidden" boolean,
  "type" character varying,
  "traffic_unit" bigint,
  "allow_extra_devices" boolean,
  "max_total_devices" integer,
  "price_per_gb" numeric,
  "price_per_gb_usd" numeric,
  "min_traffic_gb" integer,
  "max_traffic_gb" integer,
  "renewal_disabled" boolean,
  "change_from_disabled" boolean,
  "change_to_disabled" boolean,
  "required_plan_id" bigint,
  "max_subscriptions_per_customer" integer,
  "conversion_disabled" boolean,
  "device_step" integer,
  "min_total_devices" integer,
  "owner_partner_id" bigint,
  "installation_guide_block_type" character varying,
  "traffic_autopay_enabled" boolean,
  "traffic_autopay_gb" integer,
  "spins_per_day" numeric,
  "reset_traffic_on_purchase" boolean
);
CREATE TABLE "plan_prices" (
  "id" bigint,
  "plan_id" bigint,
  "price" numeric,
  "currency" character varying,
  "period_value" integer,
  "period_unit" character varying,
  "traffic_amount" bigint,
  "is_active" boolean,
  "created_at" timestamp with time zone,
  "price_type" character varying,
  "device_count" integer,
  "is_highlighted" boolean
);
CREATE TABLE "promo" (
  "id" bigint,
  "code" character varying,
  "bonus_days" integer,
  "max_uses" integer,
  "used_count" integer,
  "expires_at" timestamp with time zone,
  "active" boolean,
  "created_at" timestamp with time zone,
  "promo_type" character varying,
  "discount_percent" integer,
  "unlocked_plan_id" bigint,
  "owner_customer_id" uuid,
  "bonus_gb" integer,
  "allowed_plans" jsonb,
  "bot_id" bigint
);
CREATE TABLE "promo_usage" (
  "id" bigint,
  "promo_id" bigint,
  "used_at" timestamp with time zone,
  "customer_id" uuid,
  "subscription_id" bigint,
  "bot_id" bigint
);
CREATE TABLE "referral" (
  "id" bigint,
  "used_at" timestamp with time zone,
  "bonus_granted" boolean,
  "referrer_id" uuid,
  "referee_id" uuid,
  "bot_id" bigint
);
CREATE TABLE "referral_bonus_history" (
  "id" bigint,
  "referral_id" bigint,
  "purchase_id" bigint,
  "bonus_days" integer,
  "is_first_bonus" boolean,
  "granted_at" timestamp with time zone,
  "is_referee" boolean,
  "bonus_type" character varying,
  "tier_level" integer,
  "bot_id" bigint
);
CREATE TABLE "payment_method" (
  "id" character varying,
  "type" character varying,
  "title" character varying,
  "card_type" character varying,
  "last4" character varying,
  "first6" character varying,
  "expiry_month" character varying,
  "expiry_year" character varying,
  "issuer_name" character varying,
  "issuer_country" character varying,
  "is_active" boolean,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "provider" character varying,
  "provider_payment_method_id" text,
  "customer_id" uuid,
  "sbp_bank_id" character varying,
  "bot_id" bigint
);
CREATE TABLE "plan_change_history" (
  "id" bigint,
  "from_plan_id" bigint,
  "to_plan_id" bigint,
  "change_type" character varying,
  "value_before" integer,
  "value_after" integer,
  "amount_paid" numeric,
  "created_at" timestamp with time zone,
  "subscription_id" bigint,
  "customer_id" uuid,
  "promo_code" character varying
);
CREATE TABLE "device_names" (
  "subscription_id" bigint,
  "hwid" text,
  "readable_name" text,
  "updated_at" timestamp with time zone
);
CREATE TABLE "faq" (
  "id" bigint,
  "question" text,
  "answer" text,
  "sort_order" integer,
  "is_active" boolean,
  "created_at" timestamp without time zone,
  "updated_at" timestamp without time zone,
  "bot_id" bigint,
  "section_id" bigint,
  "subsection" text,
  "subsection_icon" text,
  "subsection_image_url" text
);
CREATE TABLE "faq_sections" (
  "id" bigint,
  "bot_id" bigint,
  "title" text,
  "sort_order" integer,
  "is_active" boolean,
  "created_at" timestamp without time zone,
  "updated_at" timestamp without time zone,
  "image_url" text,
  "icon" text
);
CREATE TABLE "support_ticket" (
  "id" bigint,
  "subject" character varying,
  "status" character varying,
  "created_at" timestamp without time zone,
  "updated_at" timestamp without time zone,
  "closed_at" timestamp without time zone,
  "closed_by" bigint,
  "customer_id" uuid,
  "queue_id" integer,
  "escalated_by" uuid,
  "escalated_at" timestamp with time zone,
  "bot_id" bigint,
  "first_response_at" timestamp with time zone,
  "reopen_count" integer,
  "priority" text,
  "type" text,
  "tags" text[],
  "assignee_id" uuid,
  "assigned_at" timestamp with time zone,
  "assigned_by" uuid,
  "lifecycle_version" bigint,
  "interaction_version" bigint,
  "status_changed_at" timestamp with time zone,
  "state_deadline_at" timestamp with time zone,
  "last_customer_message_id" bigint
);
CREATE TABLE "support_message" (
  "id" bigint,
  "ticket_id" bigint,
  "sender_type" character varying,
  "sender_id" uuid,
  "message" text,
  "created_at" timestamp without time zone,
  "reply_to_id" bigint,
  "edited_at" timestamp without time zone,
  "deleted_at" timestamp without time zone
);
CREATE TABLE "bot" (
  "id" bigint,
  "type" character varying,
  "token" text,
  "tg_bot_id" bigint,
  "tg_username" text,
  "partner_id" bigint,
  "is_enabled" boolean,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "domain" text,
  "admin_telegram_id" bigint,
  "sub_domain" text,
  "support_mode" text,
  "pending_balance" numeric,
  "available_balance" numeric,
  "total_earned" numeric,
  "total_withdrawn" numeric
);
CREATE TABLE "customer_unlocked_plans" (
  "id" bigint,
  "plan_id" bigint,
  "unlocked_at" timestamp with time zone,
  "promo_id" bigint,
  "customer_id" uuid
);
